# The SU2000 games this build runs. Sha1 = the EXE the hook table was built against
# (the circulating "VR 2000 Series Disc Image (Simon's)" HDD dump). Args = the operator
# launch line from the game's own *RUN.BAT. Fps = frame limiter for games that step per frame.
# Link = linked-pod multiplayer works (play.ps1 -Pod). MaxPlayers = pods in one linked game (2-4, default 2). PodArgs = launch line per pod number when linked (Ghost Train: /c1 /c2 = car, /nm /ns = network master / slave). AimHead = the game aims where you look (the aim trim tilts the head). NoWalk = no stick back/strafe (rail / ring games). WalkTurn = back/strafe turn the head the game sees (it walks where you look). NoTurn = no stick/grip turning (look-around only). Clip = visible bottom of the 2D layer (screen rows). ScreenH = height of the game's 2D screen in rows (PEARL: 248; default 288). FlicPace = videos play at the FLIC file's speed. GlyphColour = 1 bpp letters in their own colour + black drop shadow. HandXY / HeadXY = tracker position scale (default = DAC's). Lean = sticks hold a head lean of up to this many mm (the game moves you by lean). JoyAxes = thumbsticks feed the pod joystick's x/y axes. DeskConverge = window mode: distance in mm where the gun meets the view ray (default 8000). HeadCentre = the spot you stand on (at launch and each coin/start) is the pod centre (the game reads head x/y as lean). Materials = type 0x68 polygons take their texture from the PIX_SetMaterial table (Pac-Man's frightened blue ghost). HideOwnHead = don't draw the player's own head model, which the game locks just behind the eye (DAC: the view went inside it). Crouch = the crouch button (digital: Vive left menu / Index right B, held) feeds the head 400 mm lower (VPIX_CROUCH_MM): the game's crouch state is head z < player_height - 200 (DAC/DN2; Pac-Man never reads head z). HoldView = when the game freezes its in-head camera (DAC/DN2 round over), keep that camera as the position anchor with live head look, the own gun on the controller, the own body following the head and own shots hidden (it locked rigid to the face; DAC: only at GAME OVER, game_mode 3). BlitPriority = 2D bitmaps in the card's priority order (model slot +0x54); an opaque picture at the lowest priority is the background under the 3D models and texts (DAC title/intro picture hid "PRESS ... TO START" and the 3D logos). DepthFix = reversed-Z 32-bit float depth buffer, infinite far plane (distant surfaces a few units apart z-fought: floor decals showing the layer under). PrioLayers = models drawn back to front in the card's priority layers, depth cleared per layer (Olin Shotgun: back panel + big-top dome hid the targets). ScaredFace = frightened / flashing ghosts wear the game's scared eye + mouth textures (loaded but never used by the game). FlicCentre = the game passes a video's CENTRE as its position (Pac-Man attract board), not its corner. DeathBox = the black box the game puts round a dead / respawning player (objects\box*.bin) is drawn only while the camera is inside it (your own death blackout), not as a black block round other players. Boxing only (same as run_game.sh box): ForceGlove = own forearm + glove forced into the first-person view (red). HandFwdOff = character select: fed hand shifted back this many mm (also turns on ring detection for HandReachFight / HandXSpread / MenuFwdFlip). MenuFwdFlip = character select: forward axis mirrored (menu punch fires on a forward jab). HandReachFight = reach multiplier in the ring. PunchRel = "guard,gain" ring punches measured from your own resting fist (fed guard mm + distance past it x gain; Bobby 10-20: VR jabs never reached the game's 408 mm punch line). HandXSpread = "scale,mm" fists spread apart in the ring. HandZRight = right glove fed this many mm lower (live trim: left touchpad up/down, unless TrimLock). Seat2 = 2-player is the game's own Duo mode on pod 1's PC: this patch file (engine\hooks) turns it on and pod 2 plays seat 2 as a remote seat (Boxing). CdAudio = folder name under 'games' holding the game CD's audio tracks as TRACKnn.WAV (Zone Hunter music + voices: ZONE_CD). DeskBox = window mode: gloves in a guard, left / right mouse button throws a left / right punch. RingFeed = character select gets the ring's hand feed (no HandFwdOff shift, ring reach + spread; Bobby 10-20: tracking should start at character select). TrimLock = touchpad trims off and saved reach / arm height ignored (Boxing: thumbs brushing the Index pads drifted reach to 0.33, no punch landed). KoLift / KoExtra = a KO'd boxer is lifted so his lowest vertex sits on the mat (+ margin). DecalStack / DecalBias = coplanar ring-floor decals drawn in card order with a depth bias (no flicker).
$Games = [ordered]@{
    'DAC'   = @{ Name = 'Dactyl Nightmare';   Args = '/vcc /d';             Fps = 0;  Link = $true; HideOwnHead = $true; Crouch = $true; HoldView = $true; BlitPriority = $true; DepthFix = $true; DeathBox = $true; Haptic = 'dactwep=g:50:0.8,ouch=b:160:1,femouch=b:160:1,bodhit=b:120:0.9'; Sha1 = '5151a6d58b95a74fb86cb0dbd53a36d67eef7ce7' }
    'DN2'   = @{ Name = 'Dactyl Nightmare 2'; Args = '/vcc';                Fps = 0;  GlyphColour = $true; Link = $true; FlicPace = $true; Crouch = $true; HoldView = $true; DepthFix = $true; DecalStack = $true; DecalBias = '2e-5'; Haptic = 'dactwep=g:50:0.8,ouch=b:160:1,femouch=b:160:1,bodyhit=b:120:0.9'; Sha1 = '110d8f51aa1fc9b41d197d6cb2fb35bc0e488bf2' }
    'PAC'   = @{ Name = 'Pac-Man VR';         Args = '/vcc /solo';          Fps = 0;  WalkTurn = $true; TrigWalk = $true; HudScale = '0.8'; Materials = $true; FlicCentre = $true; ScaredFace = $true; BlitUnder = 'bells'; DepthFix = $true; Haptic = 'death.wav=b:400:1'; Sha1 = '8122b1e2c672363f6b0798d8af0a4b57e715199b'
                 Cd = 'PACMAN.CUE'; CdBin = 'PACMAN.BIN'; CdSha1 = 'f3be2645f89b8e06441d46346402d2625b78906d' }
    'MISS'  = @{ Name = 'Missile Command VR'; Args = '/1 /vcc /n';          Fps = 0;  GlyphColour = $true; AimHead = $true; FollowPitch = $true; StickTwist = 45; ScreenH = 248; WorldScale = '0.6'; BlitNudge = '1,2'; OnTop = 'skip.bin'; NoWalk = $true; NoTurn = $true; JoyAxes = $true; Haptic = 'laser04=g:40:0.6'; Sha1 = '457781d87ed9a5294bf1d615d08fffbaac5c8b38' }
    'GUN'   = @{ Name = 'Olin Shotgun';       Args = '/vcc';                Fps = 30; GlyphColour = $true; NoWalk = $true; PrioLayers = $true; LightWorld = $true; Haptic = 'shot=g:70:1'; Sha1 = '35ec8e0c619b2c6039773ca364ed4c350cb2c7dd' }
    'BOX'   = @{ Name = 'Virtuality Boxing';  Args = '/vcc';                Fps = 30; PolySelect = 'bulbflat'; NoTurn = $true; DepthFix = $true; HandXY = '1'; HandZ = '0.5,300'; HeadXY = 1; Lean = 300; HeadCentre = $true; TwoHands = $true
                 ForceGlove = $true; GloveTrack = $true; HandFwdOff = 400; MenuFwdFlip = $false; HandReachFight = '1.1'; PunchRel = '250,2.2'; HandXSpread = '1.2,80'; HandZRight = 40
                 TrimLock = $true; RingFeed = $true; DeskBox = $true; KoLift = $true; KoExtra = 5; DecalStack = $true; DecalBias = '2e-5'; Haptic = 'punch=b:60:0.9,hurtbit=b:160:1'; Sha1 = '3cab0abe8db32fe93a65036f71e50fae1e8e8be8'
                 Link = $true; MaxPlayers = 2; Seat2 = 'BOX_duo.patch' }
    'ZONE'  = @{ Name = 'Zone Hunter';        Args = '/e /c /T /D3 /1 /vcc'; Fps = 0; ScreenH = 248; DepthFix = $true; PictureBack = $true; PictureLock = 2; PanelWorld = $true; FreeRefLatch = $true; FreeYawMax = 40; FullPicLock = $true; DecalGap = 5; SubLargestFirst = $true; OnTop = 'sight'; FollowLatch = $true; OneSided = 'vr_logo,room0.bin*,barrel1.bin*,kickw\chest.bin#,kickw\abdomen.bin#,kickw\hip.bin#'; PolySelect = 'scorepow,room3.bin,room4.bin,powerpil,kickw\gun.bin'; Muzzle = 'kickw\gun.bin=pulse1:120'; ClampY = 'doorl.bin:*0.4,doorr.bin:*0.4,gendoorl:*0.4,gendoorr:*0.4,chuckl:*0.4,chuckr:*0.4'; MoveY = 'powerpil:-327:-392'; NearModels = 'doorl^8,doorr^8,sewer.bin^6,room0.bin,room2.bin,room3.bin,room4.bin,room49.bin,checkp,room18.bin,room52.bin'; ArmToGun = $true; TimerCopy = $true; CdAudio = 'ZONE_CD'; DecalStack = $true; DecalBias = '2e-5'; Haptic = 'pulse1=g:50:0.8,hit2stat=b:160:1'; Sha1 = '789182743b8c3eb924cfc71651301b3a0331d45d' }
    'GHOST' = @{ Name = 'Ghost Train';        Args = '/c1 /vcc'; Link = $true;  MaxPlayers = 2; PodArgs = @('/c1 /vcc /nm', '/c2 /vcc /ns');            Fps = 0;  NoWalk = $true; NoTurn = $true; Clip = 268; ScreenH = 248; GlyphColour = $true; JoyAxes = $true; TopButtons = $true; DeskConverge = 4000; Haptic = 'gun0=g:50:0.8,fire.wav=g:50:0.8,ouch=b:160:1,bodhit=b:120:0.9'; Sha1 = 'ce0a36969d418cd591c0e7f32f9e3a35c6748adc' }
    'SFL'   = @{ Name = 'Shoot For Loot';     Args = '/vcc';                Fps = 60; Link = $true; MaxPlayers = 2; PictureBack = 2; BlitPriority = $true; DepthFix = $true; DecalStack = $true; DecalBias = '2e-5'; NearModels = 'arrow0'; HideAbove = 5000; HandRoll = $true; Haptic = 'shot1=g:50:0.8,laser=g:40:0.6'; Sha1 = '426e1e7df0a5b591a1425840a18b0793d73e14d7' }
    # SU3000 / 2000E (Su3k: Pentium + SB16 + the emulated PIX2000E PCI board; Exe = its EXE name, told apart from the SU2000 one
    # by Sha1). ScreenW/ScreenH = 2D bitmap space. NoAimAssist = the game's head-gun blend narrowed to AimAssistDeg (its 65 deg glued the gun to the head in VR; 0 = no help, hard).
    # DeskDot = window-only centre sight (trap shooting has no crosshair). Mpeg = its movies play from the game folder through ffmpeg. ThumbOnB = the pod's thumb button (menu next) on stick down instead of stick up. GunNudge = right touchpad moves the gun 10 mm left/right/up/down, left touchpad left/right back/forward (saved). AimModes = left trigger flips free aim (snap on the sights only) / assisted aim (the game's own lock, the old way); saved. GunSnapNear/Far = the gun snaps to the cheek inside this many mm of the face (full / none).
    'GUN3K' = @{ Name = 'Total Recoil';       Args = '/vcc';                Fps = 60; Su3k = $true; Exe = 'GUN'; ScreenW = 320; ScreenH = 240; DepthFix = $true; WorldScale = '1'; HeadXY = 1; HandXY = '1'; NoAimAssist = $true; AimAssistDeg = 12; AimAssistFarDeg = 0; AimAssistNear = 250; AimAssistFar = 320; DeskDot = $true; ThumbOnB = $true; GunNudge = $true; AimModes = $true; GunSnapNear = 200; GunSnapFar = 300; Mpeg = $true; NoWalk = $true; Haptic = 'shot=g:70:1'; Sha1 = 'f8dffccd43703df543768a23813d89cd5f3769fe' }
    'ZERO3K' = @{ Name = 'Zero Hour';         Args = '';                    Fps = 0;  Su3k = $true; Exe = 'ZERO'; ScreenW = 640; ScreenH = 480; DepthFix = $true; StartBits = 4; DecalStack = $true; DecalGap = 5; SubLargestFirst = $true; Blit3kPrio = $true; LtrigThumb = $true; Fog3k = $true; Haptic = 'jackgun1=g:70:1,pistol=g:70:1,reload=r:40:0.5'; Sha1 = '53e799d472702bc3bca66f3cba1d0cb393f4d624' }
    'ZENECA3K' = @{ Name = 'Zeneca Migraine'; Args = '+t +p'; Fps = 0; Su3k = $true; Exe = 'ZENECA'; ScreenW = 640; ScreenH = 480; DepthFix = $true; Multiview3k = $true; Sha1 = '5ef342f2f6bb5f219d833cc3eef18abe64943a0b' }   # mostly timed scenes; trigger = start / data-glove fist; its CD narration tracks are in no dump
    # Native rebuilds (no DOS EXE runs; the engine plays the game itself from its data folder). Native = engine game; DataDir = the
    # folder name in the games folder, DataFile = a file inside it that proves it's the right one. MaxPlayers = linked pods (2-4) online.
    'BALL'  = @{ Name = 'Buggy Ball';         Native = 'buggy'; DataDir = 'BALL'; DataFile = 'RUNFILES\CARS.DBS'; Link = $true; MaxPlayers = 4; Fps = 0; JoyAxes = $true; DepthFix = $true; FlicCentre = $true; Sha1 = '' }
    'PEARL' = @{ Name = 'Sea Diving (Pearl)'; Args = '/vcc';                Fps = 0;  GlyphColour = $true; Link = $true; MaxPlayers = 2; ScreenH = 248; Haptic = 'dactwep=g:50:0.8,ouch=b:160:1,femouch=b:160:1,bodyhit=b:120:0.9'; Sha1 = '8899b1988af04002188526acc6e3381ff133b23b' }
}
